def parse_duration(s: str) -> int:
    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    total_seconds = 0
    i = 0

    while i < len(s):
        if s[i].isdigit():
            j = i + 1
            while j < len(s) and s[j].isdigit():
                j += 1
            num_str = s[i:j]
            i = j
            if s[i] in units:
                total_seconds += int(num_str) * units[s[i]]
                i += 1
            else:
                raise ValueError("Invalid unit")
        elif s[i] not in units:
            raise ValueError("Invalid character")
        else:
            total_seconds += units[s[i]]
            i += 1

    if total_seconds == 0 and not s:
        raise ValueError("Empty string")

    return total_seconds
```
