def count_islands(grid: list[str]) -> int:
    if not grid:
        return 0

    rows, cols = len(grid), len(grid[0])
    visited = set()
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]  # Right, Down, Up, Left

    def bfs(r: int, c: int):
        queue = [(r, c)]
        visited.add((r, c))
        while queue:
            row, col = queue.pop(0)
            for dr, dc in directions:
                r, c = row + dr, col + dc
                if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '1' and (r, c) not in visited:
                    visited.add((r, c))
                    queue.append((r, c))

    island_count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == '1' and (i, j) not in visited:
                bfs(i, j)
                island_count += 1

    return island_count
