def min_window(s: str, t: str) -> str:
    if not t or not s:
        return ''

    # Dictionary to hold the frequency of characters in t
    needed = {}
    for char in t:
        if char not in needed:
            needed[char] = 0
        needed[char] += 1

    # Dictionary to hold the frequency of characters in the current window
    window = {}
    left, right = 0, 0
    formed = 0
    minLen = float('inf')
    result = ""

    while right < len(s):
        char = s[right]
        if char in needed:
            window[char] = window.get(char, 0) + 1
            if window[char] <= needed[char]:
                formed += 1

        # If the window contains all characters needed at least as many times as t
        while formed == len(needed):
            if right - left + 1 < minLen:
                minLen = right - left + 1
                result = s[left:right+1]

            leftChar = s[left]
            if leftChar in needed:
                window[leftChar] -= 1
                if window[leftChar] < needed[leftChar]:
                    formed -= 1
            left += 1

        right += 1

    return result if minLen != float('inf') else ''
