To solve the n-queens problem, we can use backtracking. The idea is to try to place queens one by one in different columns, and if we cannot place a queen in any row of the current column then we return false. Once all the queens are placed successfully, we return True.

Here's how we can implement this function using the backtracking approach:

```python
def n_queens(n: int) -> int:
    def is_safe(board, row, col):
        # Check this row on left side
        for i in range(col):
            if board[row][i] == 1:
                return False

        # Check upper diagonal on left side
        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False

        # Check lower diagonal on left side
        for i, j in zip(range(row, n, 1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False

        return True

    def solve_n_queens_util(board, col):
        # base case: If all columns are filled
        if col >= len(board):
            return 1

        count = 0
        for i in range(len(board)):
            if is_safe(board, i, col):
                board[i][col] = 1  # Place queen
                count += solve_n_queens_util(board, col + 1)  # Recur for next column
                board[i][col] = 0  # BACKTRACK: Remove the queen
        return count

    board = [[0 for _ in range(n)] for _ in range(n)]
    return solve_n_queens_util(board, 0)
```

