def evaluate(expr: str) -> int:
    def evaluate_expr(tokens):
        if tokens[0] == '(':
            op, value = tokens[0], evaluate_expr(tokens[1:-1])
        elif tokens[0].isdigit():
            value = int(tokens[0])
            op = tokens[1]
