        return value

    tokens = []
    i = 0
    while i < len(expr):
        if expr[i] == ' ':
            i += 1
            continue
        elif expr[i] in '()+-*/':
            if expr[i] == '(':
                tokens.append(evaluate_expr([expr[i]] + tokens))
            else:
                tokens.append(expr[i])
            i += 1
        elif expr[i].isdigit():
            j = i + 1
