        # If pattern is exhausted and string isn't, we don't have a match
        if j == len(p):
            return False
        # Check if pattern character is exactly the same as string character or if pattern has '.'
        if i < len(s) and (p[j] == s[i] or p[j] == '.'):
            return match(i + 1, j + 1)
