def dijkstra(n: int, edges: list[tuple[int, int, int]], src: int) -> list[int]:
    from heapq import heappop, heappush
    import math

    distances = [math.inf] * n  # Initialize distances to infinity
    distances[src] = 0  # Distance to source node is 0
    heap = [(0, src)]  # Priority queue with (distance, node)

    while heap:
        dist, node = heappop(heap)
        if dist > distances[node]:
            continue

        for neighbor, weight in edges[node]:
            distance = dist + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heappush(heap, (distance, neighbor))

    # Mark unreachable nodes with -1
    for i in range(n):
        if distances[i] == math.inf:
            distances[i] = -1
    return distances
```
