def paths_with_obstacles(grid: list[list[int]]) -> int:
    rows, cols = len(grid), len(grid[0])
    def is_blocked(x, y):
        return grid[x][y] == 1

    def dfs(x, y):
        if x == rows - 1 and y == cols - 1:
            return 1
        if x >= rows or y >= cols or is_blocked(x, y):
            return 0
        return dfs(x + 1, y) + dfs(x, y + 1)

