def dijkstra(n: int, edges: list[tuple[int, int, int]], src: int) -> list[int]:
    from heapq import heappop, heappush

    def build_adjacency_list(edges):
        adj_list = [[] for _ in range(n)]
        for src, dest, weight in edges:
            adj_list[src].append((dest, weight))
        return adj_list

    def dijkstra_shortest_distances(n: int, adj_list: list[list[tuple[int, int]]], src: int) -> list[int]:
        distances = [float('inf')] * n
        visited = [False] * n
        distances[src] = 0
        heap = [(0, src)]

        while heap:
            current_distance, current_node = heappop(heap)
            visited[current_node] = True

            for neighbor, weight in adj_list[current_node]:
                new_distance = current_distance + weight
                if new_distance < distances[neighbor]:
                    distances[neighbor] = new_distance
                    heappush(heap, (new_distance, neighbor))

        return [distance if distance != float('inf') else -1 for distance in distances]

    adj_list = build_adjacency_list(edges)
    return dijkstra_shortest_distances(n, adj_list, src)
```
