def topo_sort(n: int, edges: list[tuple[int, int]]) -> list[int]:
    def dfs(node, visited, order):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor, visited, order)
        order.append(node)

    graph = {i: [] for i in range(n)}
    for u, v in edges:
        graph[u].append(v)

    visited = [False] * n
    order = []

