def parse_duration(s: str) -> int:
    units = {'d': 24 * 3600, 'h': 3600, 'm': 60, 's': 1}
    total_seconds = 0
    i = 0

    while i < len(s):
        if s[i].isdigit() or (s[i] == '-' and i == 0):
            j = i + 1
            while j < len(s) and s[j].isdigit():
                j += 1
            num = int(s[i:j])
            i = j
            unit = s[j:i].lower()
            if unit in units:
                total_seconds += num * units[unit]
            else:
                raise ValueError('Invalid unit: ' + unit)
        elif s[i] not in units:
            raise ValueError('Invalid character: ' + s[i])
        else:
            unit = s[i].lower()
            if unit in units:
                total_seconds += units[unit]
            else:
                raise ValueError('Invalid unit: ' + unit)
        i += 1

    if total_seconds == 0:
        raise ValueError('Empty string or invalid input')
    return total_seconds
