def binary_search(nums: list[int], target: int) -> int:
    def search_range(nums, target):
        def binary_search_core(nums, target, lo, hi):
            if lo > hi:
                return -1
            mid = (lo + hi) // 2
            if nums[mid] == target:
                if mid == lo or nums[mid - 1] < target:
                    return mid
                return binary_search_core(nums, target, lo, mid - 1)
            elif nums[mid] < target:
                return binary_search_core(nums, target, mid + 1, hi)
            else:
                return binary_search_core(nums, target, lo, mid - 1)
        return binary_search_core(nums, target, 0, len(nums) - 1)

    return search_range(nums, target)
