def dijkstra(n: int, edges: list[tuple[int, int, int]], src: int) -> list[int]:
    import heapq

    def shortest_distances(edges, src):
        from collections import defaultdict
        from heapq import heappush, heappop
        graph = defaultdict(list)
        for u, v, w in edges:
            graph[u].append((w, v))

        distances = [float('inf')] * n
        distances[src] = 0
        visited = [False] * n
        heap = [(0, src)]

        while heap:
            current_distance, node = heappop(heap)

            if visited[node]:
                continue

            visited[node] = True

            for distance, next_node in graph[node]:
                if distances[next_node] > distances[node] + distance:
                    distances[next_node] = distances[node] + distance
                    heappush(heap, (distances[next_node], next_node))

        return distances

    return shortest_distances(edges, src)
```
