def min_window(s: str, t: str) -> str:
    if not t or not s:
        return ""

    t_char_count = {}
    for char in t:
        if char not in t_char_count:
            t_char_count[char] = 0
        t_char_count[char] += 1

    start, end = 0, 0
    min_len = float('inf')
    min_window = ""
    char_count = {}

    for end in range(len(s)):
        if s[end] in t_char_count:
            if s[end] not in char_count:
                char_count[s[end]] = 0
            char_count[s[end]] += 1

            while all(char_count[char] >= t_char_count[char] for char in t_char_count):
                if end - start + 1 < min_len:
                    min_len = end - start + 1
                    min_window = s[start:end+1]
                if s[start] in t_char_count:
                    char_count[s[start]] -= 1
                start += 1

    return min_window if min_window else ""
