def evaluate(expr: str) -> int:
    def apply_op(op, a, b):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            return a // b  # Integer division

    def parse(expr):
        stack_ops, stack_nums = [], []
        i = 0
        while i < len(expr):
            if expr[i] == ' ':
                i += 1
                continue
            if expr[i] == '(':
                j = expr.find(')', i)
                if j == -1:
                    raise ValueError("Unmatched parentheses")
                value = parse(expr[i+1:j])
                stack_ops.append('(')
                stack_nums.append(value)
                i = j + 1
            elif expr[i] in '*/':
                while stack_ops and stack_ops[-1] in '+-':
                    stack_ops.pop()
                    b = stack_nums.pop()
                    a = stack_nums.pop()
                    stack_nums.append(apply_op(stack_ops.pop(), a, b))
                stack_ops.append(expr[i])
                i += 1
            elif expr[i] in '+-':
                while stack_ops and stack_ops[-1] in '*/':
                    stack_ops.pop()
                    b = stack_nums.pop()
                    a = stack_nums.pop()
                    stack_nums.append(apply_op(stack_ops.pop(), a, b))
                stack_ops.append(expr[i])
                i += 1
            elif expr[i] == ')':
                b = stack_nums.pop()
                while stack_ops and stack_ops[-1] != '(':
                    a = stack_nums.pop()
                    op = stack_ops.pop()
                    b = apply_op(op, a, b)
                stack_ops.pop()  # Pop '('
                stack_nums.append(b)
                i += 1
            else:
                j = i
                while j < len(expr) and expr[j].isdigit():
                    j += 1
                stack_nums.append(int(expr[i:j]))
                i = j
        while stack_ops:
            b = stack_nums.pop()
            a = stack_nums.pop()
            op = stack_ops.pop()
            stack_nums.append(apply_op(op, a, b))
        return stack_nums[0]

    return parse(expr)
```

