def parse_duration(s: str) -> int:
    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    total_seconds = 0
    i = 0

    while i < len(s):
        if s[i].isnumeric():
            num = int(s[i])
            for unit in units:
                if s[i-1] == unit:
                    total_seconds += num * units[unit]
                    break
            i += 1
        else:
            i += 1

    if not s or not total_seconds:
        raise ValueError("Invalid duration string")

    return total_seconds
